package com.agacostays.payroll.client; import com.agacostays.payroll.dto.response.AttendanceSummaryResponse; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; @Component public class AttendanceServiceClient{private final RestClient c;public AttendanceServiceClient(@Value("${service.attendance.url}")String u,RestClient.Builder b){c=b.baseUrl(u).build();}public AttendanceSummaryResponse summary(Long staffId,int m,int y){try{return c.get().uri(ub->ub.path("/api/attendance/staff/{id}/monthly").queryParam("month",m).queryParam("year",y).build(staffId)).retrieve().body(AttendanceSummaryResponse.class);}catch(Exception e){return null;}}}